func (this *Kraken) HandleOrders(client any, message map[string]any, optionalArgs ...any) {
	//
	//     {
	//         "channel": "executions",
	//         "type": "update",
	//         "data": [
	//             {
	//                 "order_id": "OK4GJX-KSTLS-7DZZO5",
	//                 "order_userref": 3,
	//                 "symbol": "BTC/USD",
	//                 "order_qty": 0.005,
	//                 "cum_cost": 0.0,
	//                 "time_in_force": "GTC",
	//                 "exec_type": "pending_new",
	//                 "side": "sell",
	//                 "order_type": "limit",
	//                 "limit_price_type": "static",
	//                 "limit_price": 26500.0,
	//                 "stop_price": 0.0,
	//                 "order_status": "pending_new",
	//                 "fee_usd_equiv": 0.0,
	//                 "fee_ccy_pref": "fciq",
	//                 "timestamp": "2023-09-22T10:33:05.709950Z"
	//             }
	//         ],
	//         "sequence": 8
	//     }
	//
	var subscription map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = subscription
	var allOrders []any = ccxt.SafeListTyped(message, "data")
	var allOrdersLength int = len(allOrders)
	if allOrdersLength > 0 {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		if ccxt.IsEqual(this.Orders, nil) {
			this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
		}
		var stored any = this.Orders
		var symbols map[string]any = map[string]any{}
		for i := 0; i < len(allOrders); i++ {
			var order any = this.SafeDict(allOrders, i, map[string]any{})
			var id *string = this.SafeString(order, "order_id")
			var parsed map[string]any = ccxt.MapTyped(this.ParseWsOrder(order))
			var symbol *string = this.SafeString(order, "symbol")
			var previousOrders map[string]any = ccxt.SafeMapTyped(stored.(*ccxt.ArrayCache).Hashmap, symbol)
			var previousOrder any = this.SafeDict(previousOrders, id)
			var newOrder any = parsed
			if !ccxt.IsEqual(previousOrder, nil) {
				var newRawOrder map[string]any = this.Extend(ccxt.GetValue(previousOrder, "info"), ccxt.GetValue(newOrder, "info"))
				newOrder = this.ParseWsOrder(newRawOrder)
			}
			var length int = ccxt.GetArrayLength(stored)
			if ccxt.IsEqual(length, limit) && (ccxt.IsEqual(previousOrder, nil)) {
				var first any = ccxt.GetValue(stored, 0)
				var symbolsByOrderId any = this.SafeDict(this.Options, "symbolsByOrderId", map[string]any{})
				if ccxt.InOp(symbolsByOrderId, ccxt.GetValue(first, "id")) {
					ccxt.Remove(symbolsByOrderId, ccxt.GetValue(first, "id"))
				}
			}
			stored.(ccxt.Appender).Append(newOrder)
			if symbol != nil {
				symbols[*symbol] = true
			}
		}
		var name string = "orders"
		client.(ccxt.ClientInterface).Resolve(this.Orders, name)
		var keys []string = ccxt.ObjectKeys(symbols)
		for i := 0; i < len(keys); i++ {
			var messageHash *string = ccxt.SafeStringPtr(ccxt.Add(name+":", ccxt.GetValue(keys, i)))
			client.(ccxt.ClientInterface).Resolve(this.Orders, messageHash)
		}
	}
}
func (this *Kraken) ParseWsOrder(order any, optionalArgs ...any) any {
	//
	// watchOrders
	//
	// open order
	//     {
	//         "order_id": "OK4GJX-KSTLS-7DZZO5",
	//         "order_userref": 3,
	//         "symbol": "BTC/USD",
	//         "order_qty": 0.005,
	//         "cum_cost": 0.0,
	//         "time_in_force": "GTC",
	//         "exec_type": "pending_new",
	//         "side": "sell",
	//         "order_type": "limit",
	//         "limit_price_type": "static",
	//         "limit_price": 26500.0,
	//         "stop_price": 0.0,
	//         "order_status": "pending_new",
	//         "fee_usd_equiv": 0.0,
	//         "fee_ccy_pref": "fciq",
	//         "timestamp": "2023-09-22T10:33:05.709950Z"
	//     }
	//
	// canceled order
	//
	//     {
	//         "timestamp": "2025-10-11T15:11:47.695226Z",
	//         "order_status": "canceled",
	//         "exec_type": "canceled",
	//         "order_userref": 0,
	//         "order_id": "OGAB7Y-BKX5F-PTK5RW",
	//         "cum_qty": 0,
	//         "cum_cost": 0,
	//         "fee_usd_equiv": 0,
	//         "avg_price": 0,
	//         "cancel_reason": "User requested",
	//         "reason": "User requested"
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var fee map[string]any = map[string]any{
		"cost":     this.SafeString(order, "fee_usd_equiv"),
		"currency": "USD",
	}
	var stopPrice *string = this.SafeString(order, "stop_price")
	var datetime *string = this.SafeString(order, "timestamp")
	return this.SafeOrder(map[string]any{
		"id":                 this.SafeString(order, "order_id"),
		"clientOrderId":      this.SafeString(order, "order_userref"),
		"info":               order,
		"timestamp":          this.Parse8601(datetime),
		"datetime":           datetime,
		"lastTradeTimestamp": nil,
		"status":             this.ParseOrderStatus(this.SafeString(order, "order_status")),
		"symbol":             this.SafeString(order, "symbol"),
		"type":               this.SafeString(order, "order_type"),
		"timeInForce":        this.SafeString(order, "time_in_force"),
		"postOnly":           nil,
		"side":               this.SafeString(order, "side"),
		"price":              this.SafeString(order, "limit_price"),
		"stopPrice":          stopPrice,
		"triggerPrice":       stopPrice,
		"cost":               this.SafeString(order, "cum_cost"),
		"amount":             this.SafeString2(order, "order_qty", "cum_qty"),
		"filled":             nil,
		"average":            this.SafeString(order, "avg_price"),
		"remaining":          nil,
		"fee":                fee,
		"trades":             nil,
	})
}
