func (this *Kraken) watchMultiHelperBody(ch chan any, unifiedName string, channelName string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbols := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbols
	var subscriptionArgs map[string]any = ccxt.GetArgMap(optionalArgs, 1, nil)
	_ = subscriptionArgs
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params

	ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	// symbols are required
	var symbolsNormalized []string = this.MarketSymbols(symbols, nil, false, true, false)
	if ccxt.IsEqual(symbolsNormalized, nil) {

		return nil
	}
	var messageHashes []any = []any{}
	for i := 0; i < len(symbolsNormalized); i++ {
		var eventTrigger *string = this.SafeString(params, "event_trigger")
		if eventTrigger != nil {
			messageHashes = append(messageHashes, this.GetMessageHash(channelName, nil, this.Symbol(ccxt.GetValue(symbolsNormalized, i))))
		} else {
			messageHashes = append(messageHashes, this.GetMessageHash(unifiedName, nil, this.Symbol(ccxt.GetValue(symbolsNormalized, i))))
		}
	}
	var request map[string]any = map[string]any{
		"method": "subscribe",
		"params": map[string]any{
			"channel": channelName,
			"symbol":  symbolsNormalized,
		},
		"req_id": this.RequestId(),
	}
	request["params"] = this.DeepExtend(request["params"], params)
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "publicV2"))

	ch <- ccxt.PanicOnError((<-this.WatchMultiple(url, messageHashes, request, messageHashes, subscriptionArgs)))
	return nil
}

